// spec: .qa/e2e/specs/add-candidate.md 4.5 · case: .qa/tests/add-candidate/AC-4-5.md · ticket #d4f6e7
// Two roles in one test (asUser): hunter_plus (claude-test, PLUS — no submission limit) and company (demo-company-1, owner of J-49).
// Written by autotest-writer 2026-11-03 (fallback path, NOT run). Submit-form selectors as in chain-daf026-visibility-1
// (also not run yet); owner-side list selectors from QA screenshots 02.11 (d4f6e7-5-owner-*.png) — heal SELECTORS only.
// Creates data: candidate «QA-AUTO-d4f6e7 J<ts>» + 1 anonymous submission to J-49 (no delete in the UI → test-data-journal.log).
// Opening the submission as the owner sets «נצפה/תה». Never touches DEMO-* jobs.
import { test, expect } from '../../fixtures';
import fs from 'fs';
import path from 'path';
import { openAddCandidate, fillStep1, identifyingIn, stamp, uniquePhone, EMPLOYERS } from './helpers';

test.describe.configure({ mode: 'serial' });

const JOURNAL = path.join(__dirname, '../../test-data-journal.log');
const J49 = '/collaborations/7e4ad713-60a0-4e68-9926-56e0ee667584';
const ts = stamp();
const FIRST = 'QA-AUTO-d4f6e7';
const LAST = `J${ts}`;
const NAME = `${FIRST} ${LAST}`;
const EMAIL = `qa-auto-d4f6e7-j${ts}@example.com`;
const ANSWER = `QA-AUTO d4f6e7 owner ${ts}`;
const FIELD = 'טכנולוגיה, מוצר, דאטה ומערכות מידע';
const EMPLOYER_RES = [EMPLOYERS.wix, EMPLOYERS.monday];

test.describe('Anonymous candidate: AI title and summary without identifying details (#d4f6e7)', () => {
  let created = false;
  let submitted = false;
  test.afterAll(() => {
    if (!created) return;
    fs.appendFileSync(
      JOURNAL,
      `${new Date().toISOString()} hunter_plus candidate «${NAME}»${submitted ? ' + anonymous submission to J-49' : ''} (add-candidate 4.5 #d4f6e7, no delete option)\n`,
    );
  });

  test('Owner of J-49 sees no employer, name or contacts in the anonymous submission of a «… – Backend ב-Wix» candidate @desktop @data #d4f6e7', async ({ asUser }) => {
    test.setTimeout(300_000);
    const phone = uniquePhone();
    const who = { names: [FIRST, LAST], employers: EMPLOYER_RES, phone, email: EMAIL };

    // ---- hunter_plus: create the candidate ----
    const hunter = await asUser('hunter_plus');
    const add = await openAddCandidate(hunter);
    await fillStep1(add, {
      first: FIRST, last: LAST, phone, email: EMAIL, field: FIELD,
      headline: `${NAME} – Backend ב-Wix`, workplace: 'Wix',
      about: 'מפתח Backend ב-Wix כבר שלוש שנים, לפני כן עבד ב-Monday.com.',
    });
    await expect(hunter.locator('#c-ai-title')).toHaveValue(/\S/, { timeout: 60_000 });
    await add.getByRole('button', { name: 'סיום', exact: true }).click();
    await expect(add).toBeHidden({ timeout: 30_000 });
    created = true;

    // ---- hunter_plus: anonymous submission to J-49 ----
    await hunter.goto(J49);
    const drawer = hunter.getByRole('dialog', { name: 'פרטי המשרה' });
    await expect(drawer.getByRole('heading', { name: 'QA company post test' })).toBeVisible();
    await drawer.getByRole('searchbox', { name: 'חיפוש מועמד' }).fill(LAST);
    await drawer.getByRole('button', { name: `הגשת ${NAME} למשרה` }).click();
    const choose = hunter.getByRole('dialog', { name: new RegExp(`^הגשת .*${LAST}`) });
    await expect(choose.getByRole('heading', { name: 'האם להגיש פרופיל מלא או אנונימי?' })).toBeVisible();
    await choose.getByText('פרופיל אנונימי', { exact: true }).click();
    await expect(choose.getByRole('radio', { name: /^פרופיל אנונימי/ })).toBeChecked();
    await expect(choose.getByRole('radio', { name: /^אין צורך ב-NDA/ })).toBeChecked();
    await choose.getByRole('button', { name: 'המשך', exact: true }).click();
    const form = hunter.getByRole('dialog', { name: /^הגשת מועמד/ }).last();
    await expect(form.getByRole('textbox', { name: 'תקציר המועמד' })).toHaveValue(/\S/, { timeout: 60_000 });
    const hunterSummary = await form.getByRole('textbox', { name: 'תקציר המועמד' }).inputValue();
    expect(identifyingIn(hunterSummary, who), `submission summary: «${hunterSummary}»`).toEqual([]); // §39 AC01–AC02
    await form.getByRole('textbox', { name: 'QA test question' }).fill(ANSWER);
    const send = form.getByRole('button', { name: 'סיום והגשה', exact: true });
    await expect(send).toBeEnabled({ timeout: 60_000 });
    await send.click();
    await expect(form).toBeHidden({ timeout: 30_000 });
    submitted = true;

    // ---- company (owner): list card, title and summary ----
    const owner = await asUser('company');
    await owner.goto(J49);
    const job = owner.getByRole('dialog', { name: 'פרטי המשרה' });
    await expect(job.getByRole('heading', { name: 'מועמדים שהוגשו' })).toBeVisible({ timeout: 30_000 });
    const rows = job.getByText('מועמד/ת אנונימי/ת', { exact: true });
    await expect(rows.first()).toBeVisible();

    // Done when: «the owner sees no «Wix» in the list card, title or summary» — whole list, incl. the old 3342cb1e (מה רצוי p.3)
    const listText = await job.innerText();
    expect(listText, 'J-49 submissions list has no «Wix»').not.toMatch(EMPLOYERS.wix);
    expect(listText, 'J-49 submissions list has no candidate last name').not.toContain(LAST);

    // Open anonymous rows newest-first until the one with our screening answer
    let dlgText = '';
    let heading = '';
    const max = Math.min(await rows.count(), 6);
    for (let i = 0; i < max && !dlgText; i++) {
      await rows.nth(i).click();
      const dlg = owner.getByRole('dialog', { name: /^הגשת מועמד/ }).last();
      await expect(dlg.getByText('הגשה אנונימית', { exact: true })).toBeVisible();
      if (await dlg.getByText(ANSWER).count()) {
        dlgText = (await dlg.innerText()).replace(/‏|‎/g, '');
        heading = (await dlg.getByRole('heading').first().innerText()).trim();
        break;
      }
      await dlg.getByRole('button', { name: 'סגירה' }).first().click();
      await expect(dlg).toBeHidden();
    }
    expect(dlgText, `anonymous submission with answer «${ANSWER}» among the first ${max} rows`).not.toBe('');
    expect(heading, 'title «הגשת מועמד/ת: <role>»').toMatch(/^הגשת מועמד\/ת:/);
    expect(identifyingIn(heading, who), `owner title: «${heading}»`).toEqual([]);
    // The dialog shows the screening answer (QA-AUTO marker) — check identifying details without it
    expect(identifyingIn(dlgText.replace(ANSWER, ''), who), 'owner dialog (summary etc.)').toEqual([]);
  });
});
